contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        require(amount > 0, "difficulty must be positive");
        uint256 before = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.AdjustDifficulty(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterDiff = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        assert(
            (!reverted && afterDiff == amount && before != afterDiff) ||
            (reverted && afterDiff == before && before != amount)
        );
    }
}

