pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        uint256 before;
        try c.currentDifficulty() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.AdjustDifficulty(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterDiff;
        try c.currentDifficulty() returns (uint256 __r) { afterDiff = __r; } catch { return; }
        assertTrue((!reverted && afterDiff == amount && before != afterDiff) ||
            (reverted && afterDiff == before && before != amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
